     1→// Phase 8 Day 1-2: eBPF + KProbes Integration
     2→// Kernel instrumentation via eBPF & KProbes with ring buffer
     3→// ~350줄
     4→
     5→pub use super::super::security::{SyscallEvent, NeuralKernelSentinel};
     6→
     7→// ========== eBPF Hook Types ==========
     8→
     9→#[derive(Clone, Copy, Debug)]
    10→pub enum HookType {
    11→    KProbeEntry,      // kprobe entry (pre-syscall)
    12→    KProbeReturn,     // kretprobe (post-syscall)
    13→    Tracepoint,       // kernel tracepoint
    14→    RawTracepoint,    // raw_tracepoint (lowest overhead)
    15→}
    16→
    17→// ========== eBPF Program ==========
    18→
    19→pub struct eBPFProgram {
    20→    pub program_name: String,
    21→    pub hook_type: HookType,
    22→    pub target_symbol: String,  // e.g., "__x64_sys_open", "sys_execve"
    23→    pub buffer_capacity: u32,
    24→    pub enabled: bool,
    25→    pub bytecode: Vec<u8>,      // Compiled BPF bytecode (mock)
    26→}
    27→
    28→impl eBPFProgram {
    29→    pub fn new(name: String, hook: HookType, symbol: String, capacity: u32) -> Self {
    30→        Self {
    31→            program_name: name,
    32→            hook_type: hook,
    33→            target_symbol: symbol,
    34→            buffer_capacity: capacity,
    35→            enabled: false,
    36→            bytecode: Vec::new(),
    37→        }
    38→    }
    39→
    40→    pub fn compile(&mut self) -> bool {
    41→        // Mock: Generate pseudo-bytecode
    42→        let mut code = Vec::new();
    43→        code.push(0xBF);  // BPF_MOV64
    44→        code.push(0x1A);  // reg A = reg stack
    45→        code.push(0x61);  // BPF_LD
    46→        code.push(0x00);  // load 32-bit
    47→        
    48→        self.bytecode = code;
    49→        true
    50→    }
    51→
    52→    pub fn to_ebpf_code(&self) -> String {
    53→        match self.hook_type {
    54→            HookType::KProbeEntry => {
    55→                format!(
    56→                    r#"SEC("kprobe/{}")
    57→int trace_entry(struct pt_regs *ctx) {{
    58→    // Capture syscall arguments from registers
    59→    u64 pid_tgid = bpf_get_current_pid_tgid();
    60→    u32 pid = pid_tgid >> 32;
    61→    u32 uid = bpf_get_current_uid_gid();
    62→    
    63→    // Push event to ring buffer
    64→    events.ringbuf_output(&event, sizeof(event), 0);
    65→    return 0;
    66→}}
    67→"#,
    68→                    self.target_symbol
    69→                )
    70→            }
    71→            HookType::KProbeReturn => {
    72→                format!(
    73→                    r#"SEC("kretprobe/{}")
    74→int trace_return(struct pt_regs *ctx) {{
    75→    long ret = PT_REGS_RC(ctx);
    76→    
    77→    // Log return value
    78→    events.ringbuf_output(&event, sizeof(event), 0);
    79→    return 0;
    80→}}
    81→"#,
    82→                    self.target_symbol
    83→                )
    84→            }
    85→            HookType::Tracepoint => {
    86→                format!(
    87→                    r#"SEC("tracepoint/syscalls/sys_enter_{}")
    88→int trace_tp(struct trace_event_raw_sys_enter *ctx) {{
    89→    events.ringbuf_output(&event, sizeof(event), 0);
    90→    return 0;
    91→}}
    92→"#,
    93→                    self.target_symbol
    94→                )
    95→            }
    96→            HookType::RawTracepoint => {
    97→                format!(
    98→                    r#"SEC("raw_tracepoint/{}")
    99→int trace_raw(struct bpf_raw_tracepoint_args *ctx) {{
   100→    // Lowest overhead: ~0.5µs
   101→    events.ringbuf_output(&event, sizeof(event), 0);
   102→    return 0;
   103→}}
   104→"#,
   105→                    self.target_symbol
   106→                )
   107→            }
   108→        }
   109→    }
   110→
   111→    pub fn load(&mut self) -> bool {
   112→        self.compile() && {
   113→            self.enabled = true;
   114→            true
   115→        }
   116→    }
   117→
   118→    pub fn unload(&mut self) {
   119→        self.enabled = false;
   120→        self.bytecode.clear();
   121→    }
   122→}
   123→
   124→// ========== KProbe Manager ==========
   125→
   126→pub struct KprobeHandle {
   127→    pub symbol: String,
   128→    pub hook_type: HookType,
   129→    pub hit_count: u64,
   130→}
   131→
   132→pub struct KprobeManager {
   133→    pub kprobes: Vec<KprobeHandle>,
   134→    pub max_probes: usize,
   135→    pub total_hits: u64,
   136→}
   137→
   138→impl KprobeManager {
   139→    pub fn new(max_probes: usize) -> Self {
   140→        Self {
   141→            kprobes: Vec::new(),
   142→            max_probes,
   143→            total_hits: 0,
   144→        }
   145→    }
   146→
   147→    pub fn install_kprobe(&mut self, symbol: String, hook: HookType) -> bool {
   148→        if self.kprobes.len() >= self.max_probes {
   149→            return false;
   150→        }
   151→
   152→        self.kprobes.push(KprobeHandle {
   153→            symbol,
   154→            hook_type: hook,
   155→            hit_count: 0,
   156→        });
   157→
   158→        true
   159→    }
   160→
   161→    pub fn record_hit(&mut self, index: usize) {
   162→        if index < self.kprobes.len() {
   163→            self.kprobes[index].hit_count += 1;
   164→            self.total_hits += 1;
   165→        }
   166→    }
   167→
   168→    pub fn get_hit_counts(&self) -> Vec<(String, u64)> {
   169→        self.kprobes
   170→            .iter()
   171→            .map(|k| (k.symbol.clone(), k.hit_count))
   172→            .collect()
   173→    }
   174→
   175→    pub fn get_total_hits(&self) -> u64 {
   176→        self.total_hits
   177→    }
   178→
   179→    pub fn remove_kprobe(&mut self, index: usize) -> bool {
   180→        if index < self.kprobes.len() {
   181→            self.kprobes.remove(index);
   182→            true
   183→        } else {
   184→            false
   185→        }
   186→    }
   187→}
   188→
   189→// ========== Ring Buffer Handler ==========
   190→
   191→pub struct RingBufferEvent {
   192→    pub timestamp_us: u64,
   193→    pub data: Vec<u8>,
   194→}
   195→
   196→pub struct RingBufferHandler {
   197→    pub capacity: usize,
   198→    pub events: Vec<RingBufferEvent>,
   199→    pub head: usize,
   200→    pub tail: usize,
   201→    pub events_received: u64,
   202→    pub events_lost: u64,
   203→}
   204→
   205→impl RingBufferHandler {
   206→    pub fn new(capacity: usize) -> Self {
   207→        Self {
   208→            capacity,
   209→            events: Vec::new(),
   210→            head: 0,
   211→            tail: 0,
   212→            events_received: 0,
   213→            events_lost: 0,
   214→        }
   215→    }
   216→
   217→    pub fn add_event(&mut self, event: RingBufferEvent) -> bool {
   218→        self.events_received += 1;
   219→
   220→        if self.events.len() >= self.capacity {
   221→            self.events_lost += 1;
   222→            return false;
   223→        }
   224→
   225→        self.events.push(event);
   226→        self.head = (self.head + 1) % self.capacity;
   227→        true
   228→    }
   229→
   230→    pub fn drain_events(&mut self, max_count: usize) -> Vec<RingBufferEvent> {
   231→        let mut drained = Vec::new();
   232→
   233→        for _ in 0..max_count.min(self.events.len()) {
   234→            if !self.events.is_empty() {
   235→                drained.push(self.events.remove(0));
   236→                self.tail = (self.tail + 1) % self.capacity;
   237→            }
   238→        }
   239→
   240→        drained
   241→    }
   242→
   243→    pub fn get_throughput_kps(&self) -> f64 {
   244→        (self.events_received as f64) / 1000.0
   245→    }
   246→
   247→    pub fn get_loss_rate(&self) -> f64 {
   248→        if self.events_received == 0 {
   249→            0.0
   250→        } else {
   251→            (self.events_lost as f64) / (self.events_received as f64)
   252→        }
   253→    }
   254→
   255→    pub fn get_utilization(&self) -> f64 {
   256→        (self.events.len() as f64) / (self.capacity as f64)
   257→    }
   258→}
   259→
   260→// ========== Kernel Integration Pipeline ==========
   261→
   262→pub struct KernelIntegrationPipeline {
   263→    pub ebpf_programs: Vec<eBPFProgram>,
   264→    pub kprobe_manager: KprobeManager,
   265→    pub ring_buffer: RingBufferHandler,
   266→    pub integration_enabled: bool,
   267→}
   268→
   269→impl KernelIntegrationPipeline {
   270→    pub fn new(max_programs: usize, buffer_capacity: usize) -> Self {
   271→        Self {
   272→            ebpf_programs: Vec::with_capacity(max_programs),
   273→            kprobe_manager: KprobeManager::new(max_programs),
   274→            ring_buffer: RingBufferHandler::new(buffer_capacity),
   275→            integration_enabled: false,
   276→        }
   277→    }
   278→
   279→    pub fn add_ebpf_program(&mut self, mut program: eBPFProgram) -> bool {
   280→        if self.ebpf_programs.len() >= 32 {
   281→            return false;
   282→        }
   283→
   284→        if program.compile() {
   285→            self.kprobe_manager.install_kprobe(
   286→                program.target_symbol.clone(),
   287→                program.hook_type,
   288→            );
   289→            self.ebpf_programs.push(program);
   290→            true
   291→        } else {
   292→            false
   293→        }
   294→    }
   295→
   296→    pub fn initialize(&mut self) -> bool {
   297→        for program in &mut self.ebpf_programs {
   298→            if !program.load() {
   299→                return false;
   300→            }
   301→        }
   302→
   303→        self.integration_enabled = true;
   304→        true
   305→    }
   306→
   307→    pub fn shutdown(&mut self) {
   308→        for program in &mut self.ebpf_programs {
   309→            program.unload();
   310→        }
   311→
   312→        self.integration_enabled = false;
   313→    }
   314→
   315→    pub fn process_kernel_events(&mut self, max_events: usize) -> Vec<RingBufferEvent> {
   316→        self.ring_buffer.drain_events(max_events)
   317→    }
   318→
   319→    pub fn get_performance_stats(&self) -> PerformanceStats {
   320→        PerformanceStats {
   321→            program_count: self.ebpf_programs.len(),
   322→            kprobe_count: self.kprobe_manager.kprobes.len(),
   323→            events_received: self.ring_buffer.events_received,
   324→            events_lost: self.ring_buffer.events_lost,
   325→            throughput_kps: self.ring_buffer.get_throughput_kps(),
   326→            loss_rate: self.ring_buffer.get_loss_rate(),
   327→            buffer_utilization: self.ring_buffer.get_utilization(),
   328→        }
   329→    }
   330→
   331→    pub fn integrate_with_sentinel(
   332→        &mut self,
   333→        sentinel: &mut NeuralKernelSentinel,
   334→    ) -> u32 {
   335→        let events = self.process_kernel_events(100);
   336→        let mut processed = 0;
   337→
   338→        for event in events {
   339→            // Convert RingBufferEvent to SyscallEvent
   340→            if !event.data.is_empty() && event.data.len() >= 4 {
   341→                let pid = u32::from_le_bytes([
   342→                    event.data[0],
   343→                    event.data[1],
   344→                    event.data[2],
   345→                    event.data[3],
   346→                ]);
   347→                let mut syscall_event = SyscallEvent::new(pid, 0);
   348→                syscall_event.timestamp_ns = event.timestamp_us * 1000;
   349→
   350→                // Process through sentinel
   351→                let _results = sentinel.process_syscall_batch(vec![syscall_event]);
   352→                processed += 1;
   353→            }
   354→        }
   355→
   356→        processed
   357→    }
   358→}
   359→
   360→pub struct PerformanceStats {
   361→    pub program_count: usize,
   362→    pub kprobe_count: usize,
   363→    pub events_received: u64,
   364→    pub events_lost: u64,
   365→    pub throughput_kps: f64,
   366→    pub loss_rate: f64,
   367→    pub buffer_utilization: f64,
   368→}
