   417→
   418→    #[test]
   419→    fn test_e4_ring_buffer_handling() {
   420→        let mut buffer = RingBufferHandler::new(100);
   421→
   422→        let event = RingBufferEvent {
   423→            timestamp_us: 1000,
   424→            data: vec![1, 2, 3, 4],
   425→        };
   426→
   427→        assert!(buffer.add_event(event));
   428→        assert_eq!(buffer.events_received, 1);
   429→
   430→        let drained = buffer.drain_events(1);
   431→        assert_eq!(drained.len(), 1);
   432→    }
   433→
   434→    #[test]
   435→    fn test_e5_kernel_integration_pipeline() {
   436→        let mut pipeline = KernelIntegrationPipeline::new(10, 100);
   437→
   438→        let program = eBPFProgram::new(
