   451→    }
   452→
   453→    #[test]
   454→    fn test_e6_performance_stats() {
   455→        let mut pipeline = KernelIntegrationPipeline::new(5, 100);
   456→
   457→        let program = eBPFProgram::new(
   458→            "stat_test".to_string(),
   459→            HookType::Tracepoint,
   460→            "test".to_string(),
   461→            1024,
   462→        );
   463→
   464→        pipeline.add_ebpf_program(program);
   465→
   466→        for _ in 0..50 {
   467→            let event = RingBufferEvent {
   468→                timestamp_us: 1000,
   469→                data: vec![1, 2, 3, 4],
   470→            };
   471→            let _ = pipeline.ring_buffer.add_event(event);
   472→        }
   473→
   474→        let stats = pipeline.get_performance_stats();
   475→        assert!(stats.throughput_kps > 0.0);
