     1→// Phase 8 Day 3-4: Kernel Module Integration
     2→// Kernel module loading, syscall hooking, dynamic instrumentation
     3→// ~400줄
     4→
     5→// ========== Kernel Module Types ==========
     6→
     7→#[derive(Clone, Debug)]
     8→pub enum ModuleState {
     9→    Unloaded,
    10→    Loading,
    11→    Loaded,
    12→    Active,
    13→    Unloading,
    14→    Failed(String),
    15→}
    16→
    17→#[derive(Clone)]
    18→pub struct KernelModule {
    19→    pub name: String,
    20→    pub path: String,
    21→    pub state: ModuleState,
    22→    pub module_id: u32,
    23→    pub load_time_ms: u32,
    24→    pub reference_count: u32,
    25→}
    26→
    27→impl KernelModule {
    28→    pub fn new(name: String, path: String, module_id: u32) -> Self {
    29→        Self {
    30→            name,
    31→            path,
    32→            state: ModuleState::Unloaded,
    33→            module_id,
    34→            load_time_ms: 0,
    35→            reference_count: 0,
    36→        }
    37→    }
    38→
    39→    pub fn load(&mut self) -> bool {
    40→        self.state = ModuleState::Loading;
    41→
    42→        // Simulate load process
    43→        let load_time = 50;  // 50ms simulated
    44→        self.load_time_ms = load_time;
    45→
    46→        // Check if module is valid
    47→        if self.path.is_empty() {
    48→            self.state = ModuleState::Failed("Invalid path".to_string());
    49→            return false;
    50→        }
    51→
    52→        self.state = ModuleState::Loaded;
    53→        self.reference_count = 1;
    54→        true
    55→    }
    56→
    57→    pub fn unload(&mut self) -> bool {
    58→        if self.reference_count > 0 {
    59→            self.state = ModuleState::Unloading;
    60→            self.reference_count -= 1;
    61→
    62→            if self.reference_count == 0 {
    63→                self.state = ModuleState::Unloaded;
    64→                true
    65→            } else {
    66→                false
    67→            }
    68→        } else {
    69→            false
    70→        }
    71→    }
    72→
    73→    pub fn activate(&mut self) -> bool {
    74→        match &self.state {
    75→            ModuleState::Loaded => {
    76→                self.state = ModuleState::Active;
    77→                self.reference_count += 1;
    78→                true
    79→            }
    80→            ModuleState::Active => {
    81→                self.reference_count += 1;
    82→                true
    83→            }
    84→            _ => false,
    85→        }
    86→    }
    87→
    88→    pub fn deactivate(&mut self) -> bool {
    89→        match &self.state {
    90→            ModuleState::Active => {
    91→                if self.reference_count > 0 {
    92→                    self.reference_count -= 1;
    93→                    if self.reference_count == 0 {
    94→                        self.state = ModuleState::Loaded;
    95→                    }
    96→                    true
    97→                } else {
    98→                    false
    99→                }
   100→            }
   101→            _ => false,
   102→        }
   103→    }
   104→
   105→    pub fn is_active(&self) -> bool {
   106→        matches!(self.state, ModuleState::Active)
   107→    }
   108→
   109→    pub fn is_loaded(&self) -> bool {
   110→        matches!(
   111→            self.state,
   112→            ModuleState::Loaded | ModuleState::Active
   113→        )
   114→    }
   115→}
   116→
   117→// ========== Syscall Hook Point ==========
   118→
   119→#[derive(Clone, Debug)]
   120→pub struct SyscallHook {
   121→    pub syscall_name: String,
   122→    pub syscall_id: u32,
   123→    pub module_id: u32,
   124→    pub hook_address: u64,
   125→    pub original_address: u64,
   126→    pub call_count: u64,
   127→}
   128→
   129→impl SyscallHook {
   130→    pub fn new(
   131→        syscall_name: String,
   132→        syscall_id: u32,
   133→        module_id: u32,
   134→    ) -> Self {
   135→        Self {
   136→            syscall_name,
   137→            syscall_id,
   138→            module_id,
   139→            hook_address: 0x0,
   140→            original_address: 0x0,
   141→            call_count: 0,
   142→        }
   143→    }
   144→
   145→    pub fn install(&mut self) -> bool {
   146→        // Simulate hook installation
   147→        self.hook_address = 0xFFFF_8000_0000_0000u64 + (self.syscall_id as u64 * 0x1000);
   148→        self.original_address = 0xFFFF_8000_1000_0000u64 + (self.syscall_id as u64 * 0x1000);
   149→        true
   150→    }
   151→
   152→    pub fn uninstall(&mut self) -> bool {
   153→        self.hook_address = 0x0;
   154→        self.original_address = 0x0;
   155→        true
   156→    }
   157→
   158→    pub fn record_call(&mut self) {
   159→        self.call_count += 1;
   160→    }
   161→}
   162→
   163→// ========== Kernel Module Manager ==========
   164→
   165→pub struct KernelModuleManager {
   166→    pub modules: Vec<KernelModule>,
   167→    pub hooks: Vec<SyscallHook>,
   168→    pub max_modules: usize,
   169→    pub total_loads: u32,
   170→    pub total_unloads: u32,
   171→}
   172→
   173→impl KernelModuleManager {
   174→    pub fn new(max_modules: usize) -> Self {
   175→        Self {
   176→            modules: Vec::new(),
   177→            hooks: Vec::new(),
   178→            max_modules,
   179→            total_loads: 0,
   180→            total_unloads: 0,
   181→        }
   182→    }
   183→
   184→    pub fn register_module(&mut self, mut module: KernelModule) -> bool {
   185→        if self.modules.len() >= self.max_modules {
   186→            return false;
   187→        }
   188→
   189→        if module.load() {
   190→            self.total_loads += 1;
   191→            self.modules.push(module);
   192→            true
   193→        } else {
   194→            false
   195→        }
   196→    }
   197→
   198→    pub fn unregister_module(&mut self, module_id: u32) -> bool {
   199→        if let Some(pos) = self.modules.iter().position(|m| m.module_id == module_id) {
   200→            if self.modules[pos].unload() {
   201→                self.total_unloads += 1;
   202→                self.modules.remove(pos);
   203→                return true;
   204→            }
   205→        }
   206→        false
   207→    }
   208→
   209→    pub fn get_module(&self, module_id: u32) -> Option<&KernelModule> {
   210→        self.modules.iter().find(|m| m.module_id == module_id)
   211→    }
   212→
   213→    pub fn get_module_mut(&mut self, module_id: u32) -> Option<&mut KernelModule> {
   214→        self.modules.iter_mut().find(|m| m.module_id == module_id)
   215→    }
   216→
   217→    pub fn install_hook(
   218→        &mut self,
   219→        syscall_name: String,
   220→        syscall_id: u32,
   221→        module_id: u32,
   222→    ) -> bool {
   223→        // Check if module exists and is loaded
   224→        if self.get_module(module_id).map_or(false, |m| m.is_loaded()) {
   225→            let mut hook = SyscallHook::new(syscall_name, syscall_id, module_id);
   226→            if hook.install() {
   227→                self.hooks.push(hook);
   228→                return true;
   229→            }
   230→        }
   231→        false
   232→    }
   233→
   234→    pub fn uninstall_hook(&mut self, syscall_id: u32) -> bool {
   235→        if let Some(pos) = self.hooks.iter().position(|h| h.syscall_id == syscall_id) {
   236→            self.hooks[pos].uninstall();
   237→            self.hooks.remove(pos);
   238→            return true;
   239→        }
   240→        false
   241→    }
   242→
   243→    pub fn get_hook(&self, syscall_id: u32) -> Option<&SyscallHook> {
   244→        self.hooks.iter().find(|h| h.syscall_id == syscall_id)
   245→    }
   246→
   247→    pub fn get_hook_mut(&mut self, syscall_id: u32) -> Option<&mut SyscallHook> {
   248→        self.hooks.iter_mut().find(|h| h.syscall_id == syscall_id)
   249→    }
   250→
   251→    pub fn record_hook_call(&mut self, syscall_id: u32) {
   252→        if let Some(hook) = self.get_hook_mut(syscall_id) {
   253→            hook.record_call();
   254→        }
   255→    }
   256→
   257→    pub fn get_active_module_count(&self) -> usize {
   258→        self.modules.iter().filter(|m| m.is_active()).count()
   259→    }
   260→
   261→    pub fn get_installed_hook_count(&self) -> usize {
   262→        self.hooks.len()
   263→    }
   264→
   265→    pub fn get_total_hook_calls(&self) -> u64 {
   266→        self.hooks.iter().map(|h| h.call_count).sum()
   267→    }
   268→}
