    28→
    29→impl NeuralKernelSentinel {
    30→    pub fn new() -> Self {
    31→        Self {
    32→            interceptor: SyscallInterceptor::new(1000),
    33→            analyzer: BehavioralAnalyzer::new(),
    34→            classifier: ThreatClassifier::new(),
    35→            response_engine: ResponseEngine::new(SecurityPolicy::Standard),
    36→            detection_count: 0,
    37→            total_latency_us: 0,
    38→            max_latency_us: 0,
    39→        }
    40→    }
    41→
    42→    // ===== E2E 파이프라인: < 100µs =====
    43→
    44→    pub fn process_syscall_batch(&mut self, events: Vec<SyscallEvent>) 
    45→        -> Vec<ClassificationResult> {
    46→        let start_ns = Self::get_time_ns();
    47→        let mut results = Vec::new();
    48→
    49→        for event in events {
    50→            // Stage 1: Syscall capture (< 5µs)
    51→            if !self.interceptor.intercept(event) {
    52→                continue;
    53→            }
    54→
    55→            // Stage 2: Behavioral analysis (< 20µs)
    56→            self.analyzer.add_event(event);
    57→            let features = self.analyzer.compute_features(event.pid);
    58→
    59→            // Stage 3: Threat classification (< 30µs)
    60→            let (threat_type, confidence) = self.classifier.classify(&features);
    61→            let result = ClassificationResult::from_classification(threat_type, confidence);
    62→
    63→            // Stage 4: Response decision (< 25µs)
    64→            if confidence > 0.5 {
    65→                let _actions = self.response_engine.respond(&result, event.pid);
    66→                self.detection_count += 1;
    67→            }
    68→
    69→            results.push(result);
    70→        }
    71→
    72→        let elapsed_us = (Self::get_time_ns() - start_ns) / 1000;
    73→        self.total_latency_us += elapsed_us;
    74→        self.max_latency_us = self.max_latency_us.max(elapsed_us);
    75→
    76→        results
    77→    }
    78→
    79→    pub fn detect_zero_day(&self, pid: u32) -> Option<f64> {
    80→        if let Some(window) = self.analyzer.ngram_extractor.per_pid_windows.get(&pid) {
    81→            if window.is_empty() {
    82→                return None;
    83→            }
    84→
    85→            // Unknown N-gram 검출
    86→            let mut unknown_count = 0;
    87→            for ngram in self.analyzer.ngram_extractor.ngram_counts.keys() {
    88→                if self.analyzer.ngram_extractor.ngram_counts[ngram] == 1 {
    89→                    unknown_count += 1;
    90→                }
    91→            }
    92→
    93→            let anomaly_ratio = unknown_count as f64 / window.len() as f64;
    94→            if anomaly_ratio > 0.3 {
    95→                return Some(anomaly_ratio.min(1.0));
    96→            }
    97→        }
    98→
    99→        None
   100→    }
   101→
   102→    pub fn get_accuracy_metrics(&self) -> AccuracyMetrics {
   103→        AccuracyMetrics {
   104→            total_detections: self.detection_count,
   105→            avg_latency_us: if self.detection_count > 0 {
   106→                self.total_latency_us / self.detection_count as u64
   107→            } else {
   108→                0
   109→            },
   110→            p99_latency_us: self.max_latency_us,
   111→            false_positive_rate: self.response_engine.get_false_positive_rate(),
   112→            accuracy: self.response_engine.get_accuracy(),
   113→        }
   114→    }
   115→
   116→    pub fn set_policy(&mut self, policy: SecurityPolicy) {
   117→        self.response_engine.set_policy(policy);
   118→    }
   119→
   120→    fn get_time_ns() -> u64 {
   121→        SystemTime::now()
   122→            .duration_since(UNIX_EPOCH)
   123→            .unwrap()
   124→            .as_nanos() as u64
   125→    }
   126→}
