     5→// ========== Cache Strategy ==========
     6→
     7→#[derive(Clone)]
     8→pub struct HookCallCache {
     9→    pub syscall_id: u32,
    10→    pub last_call_result: Option<u64>,
    11→    pub call_frequency: u32,
    12→    pub cache_hits: u64,
    13→    pub cache_misses: u64,
    14→}
    15→
    16→impl HookCallCache {
    17→    pub fn new(syscall_id: u32) -> Self {
    18→        Self {
    19→            syscall_id,
    20→            last_call_result: None,
    21→            call_frequency: 0,
    22→            cache_hits: 0,
    23→            cache_misses: 0,
    24→        }
    25→    }
    26→
    27→    pub fn lookup(&mut self) -> Option<u64> {
    28→        match self.last_call_result {
    29→            Some(result) => {
    30→                self.cache_hits += 1;
    31→                Some(result)
    32→            }
    33→            None => {
    34→                self.cache_misses += 1;
    35→                None
    36→            }
    37→        }
    38→    }
    39→
    40→    pub fn update(&mut self, result: u64) {
    41→        self.last_call_result = Some(result);
    42→        self.call_frequency = (self.call_frequency + 1).min(255);
    43→    }
    44→
    45→    pub fn get_hit_rate(&self) -> f64 {
    46→        let total = self.cache_hits + self.cache_misses;
    47→        if total == 0 {
    48→            0.0
    49→        } else {
    50→            (self.cache_hits as f64) / (total as f64)
    51→        }
    52→    }
    53→
    54→    pub fn invalidate(&mut self) {
    55→        self.last_call_result = None;
    56→    }
    57→}
